// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        uint256 initialTotalDistributed = 200000000e18;
        uint256 initialTotalRemaining = c.totalRemaining();

        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("getTokens()"));

        (bool success2, ) = address(c).call(abi.encodeWithSignature("XBornID()"));

        uint256 finalTotalDistributed = c.totalDistributed();

        // The reference contract adds distribution amounts, so totalDistributed should never decrease below initial value.
        assertTrue(finalTotalDistributed >= initialTotalDistributed);
    }
}

